public static void check(Solution solution) {
    assert Arrays.equals(solution.flipEquiv(new int[]{1,2,3}, new int[]{1,3,2}), True);
    assert Arrays.equals(solution.flipEquiv(new int[]{1,2,3,4,5}, new int[]{1,3,2,5,4}), False);
    assert Arrays.equals(solution.flipEquiv(new int[]{}, new int[]{1}), False);
    assert Arrays.equals(solution.flipEquiv(new int[]{1,2,3,4,5,6,7}, new int[]{1,3,2,7,6,5,4}), True);
    assert Arrays.equals(solution.flipEquiv(new int[]{}, new int[]{}), True);
    assert Arrays.equals(solution.flipEquiv(new int[]{1,2,3,4,5,6,null,null,null,7,8}, new int[]{1,3,2,null,6,4,5,null,null,null,null,8,7}), True);
    assert Arrays.equals(solution.flipEquiv(new int[]{1,2,3,4}, new int[]{1,3,2,4}), False);
    assert Arrays.equals(solution.flipEquiv(new int[]{1}, new int[]{1}), True);
    assert Arrays.equals(solution.flipEquiv(new int[]{1,2}, new int[]{1,null,2}), True);
    assert Arrays.equals(solution.flipEquiv(new int[]{1,2,3,4}, new int[]{1,3,2,null,4}), False);
    assert Arrays.equals(solution.flipEquiv(new int[]{1,null,2,null,3}, new int[]{1,2,null,3}), True);
